const TriangleAlertIcon: Icon = /* @__PURE__ */ createIcon("triangle-alert", iconNode5)

const DOT = "\u2022"

/** Fixed-length mask so the dots never leak the length of the secret. */
function Mask({ value, peek }: { value: string; peek: boolean }) {
  return (
    <>
      <span aria-hidden="true" className="tracking-[0.12em]">
        {DOT.repeat(12)}
      </span>
      {peek && value.length > 8 ? (
        <span className="text-(color:--chatcn-fg-muted)">{value.slice(-4)}</span>
      ) : null}
    </>
  )
}

interface TooltipProps {
  content: React.ReactNode
  children: React.ReactElement
  side?: "top" | "bottom" | "left" | "right"
  align?: "start" | "center" | "end"
  /** A shortcut hint shown after the label, for example `⌘C`. */
  shortcut?: React.ReactNode
}

function Tooltip({ content, children, side = "top", align = "center", shortcut }: TooltipProps) {
  return (
    <TooltipPrimitive.Root>
      <TooltipPrimitive.Trigger render={children} />
      <TooltipPrimitive.Portal>
        <TooltipPrimitive.Positioner side={side} align={align} sideOffset={6} className="z-50">
          <TooltipPrimitive.Popup
            data-slot="tooltip"
            className={cn(
              "rounded-(--chatcn-radius-sm) bg-(color:--chatcn-fg) text-[0.75rem]/[1rem] text-(color:--chatcn-bg) shadow-(--chatcn-shadow-md) flex max-w-xs origin-(--transform-origin) items-center gap-2 px-2 py-1 font-medium text-pretty",
              "ease-(--chatcn-ease-out) transition-[opacity,scale] duration-125",
              "data-[ending-style]:scale-97 data-[ending-style]:opacity-0 data-[ending-style]:duration-100 data-[starting-style]:scale-97 data-[starting-style]:opacity-0",
              // Once one tooltip is open, the next appears without animation. Reduced motion keeps
              // only the fade.
              "data-[instant]:transition-none motion-reduce:transition-opacity motion-reduce:data-[ending-style]:scale-100 motion-reduce:data-[starting-style]:scale-100",
            )}
          >
            {content}
            {shortcut ? <span className="font-normal opacity-60">{shortcut}</span> : null}
          </TooltipPrimitive.Popup>
        </TooltipPrimitive.Positioner>
      </TooltipPrimitive.Portal>
    </TooltipPrimitive.Root>
  )
}

/* -------------------------------------------------------------------------------------------------
 * Row
 * -----------------------------------------------------------------------------------------------*/

function VariableRow({
  variable,
  revealAll,
  peek,
}: {
  variable: EnvironmentVariable
  revealAll: boolean
  peek: boolean
}) {
  const [revealed, setRevealed] = React.useState(false)
  // A keyboard reveal swaps instantly; a pointer reveal crossfades.
  const [animate, setAnimate] = React.useState(false)
  const missing = isMissing(variable)
  const secret = isSecret(variable) && !missing
  const visible = !secret || revealed || revealAll
  const value = variable.value ?? ""

  React.useEffect(() => {
    if (!revealAll) setRevealed(false)
  }, [revealAll])

  return (
    <li
      data-slot="environment-variable"
      data-missing={missing ? "" : undefined}
      // Narrow lists stack the value under its key, so keys read whole instead of in fragments.
      className="group/row grid min-h-11 grid-cols-[minmax(0,1fr)_auto] items-center gap-x-4 gap-y-1 py-1.5 ps-4 pe-2 @lg/env:grid-cols-[minmax(0,2fr)_minmax(0,3fr)_auto] @lg/env:gap-y-0"
    >
      <div className="col-start-1 row-start-1 flex min-w-0 flex-col">
        <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg) flex min-w-0 flex-wrap items-baseline gap-x-2 font-mono font-medium">
          {/* A key is a name, so it never hides: long keys wrap after an underscore
              (NEXT_PUBLIC_STRIPE_ / PUBLISHABLE_KEY), and only mid-word when a part alone is too wide. */}
          <span className="min-w-0 [overflow-wrap:anywhere]">
            {variable.key.split("_").map((part, i, parts) => (
              <React.Fragment key={i}>
                {part}
                {i < parts.length - 1 ? (
                  <>
                    _<wbr />
                  </>
                ) : null}
              </React.Fragment>
            ))}
          </span>
          {variable.required && !missing ? (
            <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) shrink-0 font-sans font-normal">
              Required
            </span>
          ) : null}
        </span>
        {variable.description ? (
          <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) truncate">
            {variable.description}
          </span>
        ) : null}
      </div>

      <div className="text-[0.8125rem]/[1.25rem] col-start-1 row-start-2 flex min-w-0 items-center font-mono @lg/env:col-start-2 @lg/env:row-start-1">
        {missing ? (
          <span
            className={cn(
              "text-[0.75rem]/[1rem] inline-flex items-center gap-1.5 font-sans",
              variable.required ? "text-(color:--chatcn-red)" : "text-(color:--chatcn-fg-subtle)",
            )}
          >
            {variable.required ? (
              <TriangleAlertIcon aria-hidden="true" className="size-3.5" />
            ) : null}
            {variable.required ? "Missing" : "Not set"}
          </span>
        ) : (
          <span
            key={visible ? "shown" : "masked"}
            data-masked={visible ? undefined : ""}
            className={cn(
              "min-w-0 truncate",
              visible ? "text-(color:--chatcn-fg-muted) select-all" : "text-(color:--chatcn-fg-subtle) select-none",
              animate && "motion-safe:animate-[chatcn-swap_150ms_var(--chatcn-ease-out)]",
            )}
            title={visible ? value : undefined}
          >
            {visible ? value : <Mask value={value} peek={peek} />}
            {visible ? null : <span className="sr-only">Hidden value</span>}
          </span>
        )}
      </div>

      <div className="col-start-2 row-span-2 row-start-1 flex items-center gap-0.5 @lg/env:col-start-3 @lg/env:row-span-1">
        {secret ? (
          <Tooltip content={visible ? "Hide value" : "Reveal value"}>
            <Button
              size="icon-sm"
              aria-label={`${visible ? "Hide" : "Reveal"} ${variable.key}`}
              aria-pressed={visible}
              disabled={revealAll}
              onClick={(event) => {
                setAnimate(event.detail !== 0)
                setRevealed((r) => !r)
              }}
              className="pointer-coarse:size-11"
            >
              {visible ? <EyeOffIcon /> : <EyeIcon />}
            </Button>
          </Tooltip>
        ) : (
          <span className="size-7 pointer-coarse:size-11" />
        )}
        {missing ? (
          // Nothing to copy: keep the column, skip the dead button.
          <span className="size-7 pointer-coarse:size-11" />
        ) : (
          <CopyButton
            size="icon-sm"
            label={`Copy ${variable.key}`}
            value={value}
            className="pointer-coarse:size-11"
          />
        )}
      </div>
    </li>
  )
}

/* -------------------------------------------------------------------------------------------------
 * EnvironmentVariables
 * -----------------------------------------------------------------------------------------------*/

export function EnvironmentVariables({
  variables,
  title = "Environment variables",
  source,
  peek = false,
  revealed: revealedProp,
  defaultRevealed = false,
  onRevealedChange,
  warning,
  className,
  ...props
}: EnvironmentVariablesProps) {
  const [revealedState, setRevealedState] = React.useState(defaultRevealed)
  const revealAll = revealedProp ?? revealedState
  const setRevealAll = (next: boolean) => {
    if (revealedProp === undefined) setRevealedState(next)
    onRevealedChange?.(next)
  }

  const missing = variables.filter((v) => v.required && isMissing(v))
  const hasSecrets = variables.some((v) => isSecret(v) && !isMissing(v))
  const dotenv = () =>
    variables
      .filter((v) => !isMissing(v))
      .map((v) => `${v.key}=${quote(v.value ?? "")}`)
      .join("\n")

  const shownWarning =
    warning !== undefined
      ? warning
      : missing.length > 0
        ? `${missing.length === 1 ? `${missing[0]?.key} is required but not set` : `${missing.length} required variables are not set`}. Add ${missing.length === 1 ? "it" : "them"} to ${source ?? "your environment"}, then restart the server.`
        : null

  return (
    <div
      data-slot="environment-variables"
      className={cn(
        "rounded-(--chatcn-radius-lg) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm) text-(color:--chatcn-fg) @container/env overflow-hidden",
        "forced-colors:outline-1 forced-colors:outline-solid",
        className,
      )}
      {...props}
    >
      <div className="border-(color:--chatcn-border)/70 flex min-h-11 items-center gap-2 border-b py-1.5 ps-4 pe-2">
        {/* Narrow cards put the file and count under the title, so neither is cut to a letter. */}
        <div className="flex min-w-0 flex-1 flex-col @lg/env:flex-row @lg/env:items-baseline @lg/env:gap-2">
          <span className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] truncate font-medium">{title}</span>
          <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex min-w-0 items-baseline gap-2">
            {source ? (
              <>
                <span className="truncate font-mono">{source}</span>
                <span aria-hidden="true">·</span>
              </>
            ) : null}
            <span className="shrink-0 tabular-nums">
              {variables.length} {variables.length === 1 ? "variable" : "variables"}
            </span>
          </span>
        </div>
        {hasSecrets ? (
          <Button
            size="sm"
            aria-pressed={revealAll}
            onClick={() => setRevealAll(!revealAll)}
            className="pointer-coarse:h-11"
          >
            {revealAll ? <EyeOffIcon /> : <EyeIcon />}
            {revealAll ? "Hide all" : "Reveal all"}
          </Button>
        ) : null}
        {variables.some((v) => !isMissing(v)) ? (
          <CopyButton
            size="icon-sm"
            label="Copy as .env"
            value={dotenv}
            className="pointer-coarse:size-11"
          />
        ) : null}
      </div>

      {shownWarning ? (
        <div
          role="alert"
          className="border-(color:--chatcn-border)/70 text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) flex items-start gap-2.5 border-b px-4 py-3 text-pretty"
        >
          <TriangleAlertIcon
            aria-hidden="true"
            className="text-(color:--chatcn-red) mt-0.5 size-4 shrink-0"
          />
          <p>{shownWarning}</p>
        </div>
      ) : null}

      {variables.length === 0 ? (
        <div className="flex flex-col gap-1 px-4 py-8 text-center">
          <p className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] font-medium">No variables yet</p>
          <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) text-pretty">
            Add keys to {source ?? "a .env file"} and they show up here, masked by default.
          </p>
        </div>
      ) : (
        <ul
          aria-label={typeof title === "string" ? title : "Environment variables"}
          className="divide-(color:--chatcn-border)/60 divide-y py-0.5"
        >
          {variables.map((variable) => (
            <VariableRow key={variable.key} variable={variable} revealAll={revealAll} peek={peek} />
          ))}
        </ul>
      )}
    </div>
  )
}

export default EnvironmentVariables

